param([switch]$SelfTest)
$ErrorActionPreference = 'Stop'
$hosts = @('homologacao.nfe.fazenda.sp.gov.br','nfe-homologacao.svrs.rs.gov.br','hom.sefazvirtual.fazenda.gov.br')
if($SelfTest){if($hosts.Count -ne 3){throw 'SELF_TEST_HOSTS_FAILED'};Write-Host 'M13_G14_TLS_SELF_TEST_OK';exit 0}
Add-Type -AssemblyName System.Security
$store=New-Object System.Security.Cryptography.X509Certificates.X509Store([System.Security.Cryptography.X509Certificates.StoreName]::My,[System.Security.Cryptography.X509Certificates.StoreLocation]::CurrentUser)
try{$store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadOnly);$now=[DateTime]::UtcNow;$candidates=New-Object System.Security.Cryptography.X509Certificates.X509Certificate2Collection;foreach($certificate in $store.Certificates){if($certificate.HasPrivateKey -and $certificate.NotBefore.ToUniversalTime() -le $now -and $certificate.NotAfter.ToUniversalTime() -ge $now){[void]$candidates.Add($certificate)}};$selected=[System.Security.Cryptography.X509Certificates.X509Certificate2UI]::SelectFromCollection($candidates,'Select A1 for TLS-only homologation probe','No HTTP, SOAP, XML or fiscal payload will be sent.',[System.Security.Cryptography.X509Certificates.X509SelectionFlag]::SingleSelection);if($selected.Count -ne 1){Write-Host 'M13_G14_CANCELLED';exit 2};foreach($hostName in $hosts){$tcp=New-Object System.Net.Sockets.TcpClient;$ssl=$null;try{$tcp.Connect($hostName,443);$ssl=New-Object System.Net.Security.SslStream($tcp.GetStream(),$false);$ssl.AuthenticateAsClient($hostName,$selected,[System.Security.Authentication.SslProtocols]::Tls12,$true);Write-Host ('M13_G14_TLS_OK host={0} tcp=True tls=True mutualTlsCertificatePresented=True applicationBytesSent=0 protocol={1}' -f $hostName,$ssl.SslProtocol)}catch{Write-Host ('M13_G14_TLS_FAIL host={0} applicationBytesSent=0 errorType={1}' -f $hostName,$_.Exception.GetType().Name)}finally{if($null -ne $ssl){$ssl.Dispose()};$tcp.Dispose()}}}finally{$store.Close()}
